begin;
-- Restore the existing MIGO permission lost in the cash authorization map.
-- No grants, approvals, tenant availability or data are changed.
create or replace function app_private.assert_operational_permission(p_tenant_id uuid,p_permission_key text,p_branch_id uuid default null)
returns uuid language plpgsql stable security definer set search_path='' set row_security=off as $fn$
declare actor_id uuid; required_codes text[]; ready_count integer;
begin
  if coalesce(auth.role(),'')<>'authenticated' or auth.uid() is null then raise exception 'Authenticated session required' using errcode='42501'; end if;
  actor_id:=auth.uid();
  if p_tenant_id is null or p_permission_key is null or not exists(select 1 from public.companies where id=p_tenant_id and status='active') or not app_private.is_active_company_member(p_tenant_id) or (p_branch_id is not null and not app_private.can_access_branch(p_tenant_id,p_branch_id)) or not app_private.has_tenant_permission(p_tenant_id,p_permission_key,p_branch_id) or not exists(select 1 from public.permission_definitions where permission_key=p_permission_key and approval_state='approved') then raise exception 'Operational permission denied' using errcode='42501'; end if;
  required_codes:=case
    when p_permission_key in ('transaction.masterdata.party.read','transaction.masterdata.party.manage') then array['BP01'] when p_permission_key='transaction.masterdata.catalog.read' then array['MM01','SV01'] when p_permission_key='transaction.masterdata.catalog.product.manage' then array['MM01'] when p_permission_key='transaction.masterdata.catalog.service.manage' then array['SV01'] when p_permission_key in ('transaction.inventory.stock.read','transaction.inventory.stock.move') then array['MIGO'] when p_permission_key='transaction.purchasing.purchase_order.read' then array['ME23N'] when p_permission_key='transaction.purchasing.purchase_order.create' then array['ME21N'] when p_permission_key='transaction.masterdata.catalog.product.update' then array['MM02'] when p_permission_key='transaction.masterdata.catalog.product.read' then array['MM03'] when p_permission_key='transaction.inventory.balance.read' then array['MB52'] when p_permission_key='transaction.inventory.history.read' then array['MB51'] when p_permission_key='transaction.inventory.physical.create' then array['MI01'] when p_permission_key='transaction.inventory.physical.count' then array['MI04'] when p_permission_key='transaction.inventory.physical.adjust' then array['MI07'] when p_permission_key='transaction.inventory.transfer' then array['ZTR01'] when p_permission_key='transaction.service_order.create' then array['ZOS01'] when p_permission_key='transaction.service_order.update' then array['ZOS02'] when p_permission_key='transaction.service_order.read' then array['ZOS03'] when p_permission_key='transaction.service_order.close' then array['ZOS04'] when p_permission_key='transaction.purchasing.receipt.manage' then array['ZGR01'] when p_permission_key='transaction.inventory.valuation.initial' then array['ZIV01'] when p_permission_key='transaction.quotation.create' then array['ZQT01'] when p_permission_key='transaction.quotation.manage' then array['ZQT02'] when p_permission_key='transaction.quotation.read' then array['ZQT03'] when p_permission_key='transaction.quotation.approve' then array['ZQT04'] when p_permission_key='transaction.sales.order.create' then array['ZVE01'] when p_permission_key='transaction.sales.order.manage' then array['ZVE02'] when p_permission_key='transaction.sales.order.read' then array['ZVE03'] when p_permission_key='transaction.sales.order.decide' then array['ZVE04'] when p_permission_key='transaction.finance.payable.manage' then array['ZFI01'] when p_permission_key='transaction.finance.receivable.manage' then array['ZFI02'] when p_permission_key='transaction.finance.settlement.manage' then array['ZFI03'] when p_permission_key='transaction.finance.read' then array['ZFI04'] when p_permission_key='transaction.cash.register.open' then array['ZCX01'] when p_permission_key='transaction.cash.register.move' then array['ZCX02'] when p_permission_key='transaction.cash.register.close' then array['ZCX03'] when p_permission_key='transaction.cash.register.read' then array['ZCX04'] else null end;
  -- Keep mappings introduced by the already-published Sales Inventory and Billing
  -- migrations. This migration intentionally extends (rather than narrows) the
  -- central authorization contract.
  if p_permission_key='transaction.sales.inventory.reserve' then required_codes:=array['ZVE05']; end if;
  if p_permission_key='transaction.sales.inventory.fulfill' then required_codes:=array['ZVE06']; end if;
  if p_permission_key='transaction.sales.inventory.return' then required_codes:=array['ZVE07']; end if;
  if p_permission_key='transaction.billing.issue' then required_codes:=array['ZFB01']; end if;
  if p_permission_key='transaction.billing.read' then required_codes:=array['ZFB02']; end if;
  if p_permission_key='transaction.billing.cancel' then required_codes:=array['ZFB03']; end if;
  if required_codes is null then raise exception 'Operational permission is not mapped to an approved transaction' using errcode='42501'; end if;
  select count(distinct c.transaction_code) into ready_count from public.erp_transaction_authorization_catalog c join public.permission_definitions p on p.permission_key=c.permission_key and p.approval_state='approved' join public.company_module_availability m on m.tenant_id=p_tenant_id and m.module_code=c.module_code and m.enabled join public.company_transaction_availability t on t.tenant_id=p_tenant_id and t.transaction_code=c.transaction_code and t.enabled where c.transaction_code=any(required_codes) and c.approval_state='approved';
  if ready_count<>cardinality(required_codes) then raise exception 'Operational transaction is not approved or available for this company' using errcode='42501'; end if;
  return actor_id;
end;$fn$;
alter function app_private.assert_operational_permission(uuid,text,uuid) owner to postgres;
revoke all on function app_private.assert_operational_permission(uuid,text,uuid) from public,anon,authenticated,service_role;
commit;
